#pragma once

#include "PlutoGE/render/DetailGrass.h"
#include "PlutoGE/scene/components/Component.h"

#include <cstdint>
#include <memory>
#include <string>
#include <vector>

namespace PlutoGE::scene
{
    class TerrainComponent;

    // Dense ground cover over a terrain, generated by the GPU around the camera every frame (docs/DETAIL_GRASS.md).
    // Goes on the entity of the TerrainComponent it grows on. Each layer is one kind of cover (grass, dry grass,
    // flowers): where it grows comes from the painted weight of a terrain layer, and its roots take the colour of the
    // terrain's macro albedo, so painting the terrain repaints the grass. Nothing per clump is stored in the scene.
    class DetailGrassComponent : public TypedComponent<DetailGrassComponent>
    {
    public:
        static constexpr std::size_t MaxLayers = 8;

        struct Layer
        {
            render::DetailGrassLayer settings;
            // Name of the terrain layer whose painted weight is this layer's density; empty grows everywhere.
            std::string densityLayer;
            // Material asset the clumps shade with; empty uses render::DetailGrassDefaultMaterial.
            std::string materialAsset;

            bool operator==(const Layer &) const = default;
        };

        // A new component grows one meadow layer everywhere on its terrain.
        DetailGrassComponent() { m_layers.push_back(Sanitized({render::DetailGrassPresetLayer(render::DetailGrassPreset::Meadow)})); }

        // Generation is a pure function of the camera; there is nothing to step.
        void Update(float) override {}
        bool RequiresFrameUpdate() const override { return false; }
        std::vector<Property> Serialize() const override;
        void Deserialize(const std::vector<Property> &properties) override;

        const std::vector<Layer> &GetLayers() const { return m_layers; }
        // At most MaxLayers are kept; settings are sanitized.
        void SetLayers(std::vector<Layer> layers);
        bool AddLayer(Layer layer);
        void SetLayer(std::size_t index, Layer layer);
        void RemoveLayer(std::size_t index);

        // The TerrainComponent on the same entity, or null.
        TerrainComponent *GetTerrain() const;
        // The terrain's drawn surface (TerrainComponent::GetSurfaceSampleHeight) and holes, rebuilt when the terrain
        // changes and otherwise shared, so the renderer uploads it once. Null without a terrain.
        std::shared_ptr<const render::DetailGrassHeightField> GetHeightField() const;

    private:
        static Layer Sanitized(Layer layer);

        std::vector<Layer> m_layers;
        mutable std::shared_ptr<const render::DetailGrassHeightField> m_heightField;
        // What m_heightField was built from: the terrain's revisions and grid.
        mutable const TerrainComponent *m_heightTerrain = nullptr;
        mutable std::uint64_t m_heightRevision = 0, m_holeRevision = 0;
        mutable int m_heightColumns = 0, m_heightRows = 0;
        mutable float m_heightCellSize = 0.0f, m_heightSmoothing = 0.0f;
        mutable std::uint64_t m_heightFieldRevision = 0;
    };
}
